# I accidentally broke images on https://www.botscabin.com/drop-lookout when I re-fetched
# all of the images on ttvdrops.

# Copy the map somewhere nginx can read:
# sudo cp tools/nginx/boxart-fallback.map /etc/nginx/boxart-fallback.map
# Include it inside the http {} block in /etc/nginx/nginx.conf:
# http {
#     include /etc/nginx/boxart-fallback.map;
# 
#     # ... existing config ...
# }
# Then add this to the server {} block that serves the site. If you already have a location /media/, just add the error_page line to it instead of duplicating it:
# location /media/ {
#     error_page 404 = @box_art_fallback;
# 
#     # ... your existing root/alias ...
# }
# 
# location @box_art_fallback {
#     if ($box_art_fallback = "") {
#         return 404;
#     }
#     if ($uri = $box_art_fallback) {
#         return 404;
#     }
#     return 302 $box_art_fallback;
# }
# Then:
# sudo nginx -t
# sudo systemctl reload nginx
# Use 302 while testing. Change it to 301 later if you want permanent redirects.


# Extract the game ID from any box-art filename:
#   229772247_oRRcc9f.jpg -> 229772247
map $uri $box_art_game_id {
    ~*^/media/games/box_art/(?<box_art_id>[0-9]+)(?:_[^/]+)?\.(?:jpe?g|png|webp|avif)$ $box_art_id;
    default "";
}

# Resolve that game ID to its current local box-art path.
